function getBoolean(name, defaultValue) {
  const val = getInput(name);
  if (!val) return defaultValue;
  return val.toLowerCase() === "true";
}
async function run() {
  try {
    const profilesDir = getInput("profiles-directory") || "force-app/main/default/profiles";
    const outputDir = getInput("output-directory") || "force-app/main/default";
    const strictParity = getBoolean("strict-parity", true);
    const blockProfilePermissions = getBoolean("block-profile-permissions", true);
    const maxComplexityScore = parseInt(getInput("max-complexity-score") || "75", 10);
    const failOnRisk = getBoolean("fail-on-risk", false);
    const postPrComment = getBoolean("post-pr-comment", true);
    const githubToken = getInput("github-token") || process.env.GITHUB_TOKEN;
    info(`\u{1F6E1}\uFE0F PermForge Security & Parity Gate starting...`);
    info(`\u2022 Profiles Directory: ${profilesDir}`);
    info(`\u2022 Strict Parity Gate: ${strictParity}`);
    info(`\u2022 Block Profile Permissions: ${blockProfilePermissions}`);
    info(`\u2022 Max Complexity Score: ${maxComplexityScore}`);
    const options = {
      profilesDir,
      outputDir,
      strictParity,
      blockProfilePermissions,
      maxComplexityScore,
      failOnRisk,
      postPrComment,
      githubToken
    };
    const runner = new PermForgeGateRunner();
    const result = await runner.runGate(options);
    setOutput("passed", result.passed);
    setOutput("profiles-scanned", result.totalProfilesScanned);
    setOutput("permission-creep-count", result.totalPermissionCreep);
    setOutput("parity-failures", result.parityFailureCount);
    setOutput("average-complexity-debt", result.averageComplexityDebt);
    if (!result.passed) {
      setFailed(`PermForge Security Gate failed due to policy violations or parity discrepancies.`);
    } else {
      info(`\u2714 PermForge Security Gate passed successfully!`);
    }
  } catch (error3) {
    setFailed(`PermForge Gate execution error: ${error3.message}`);
  }
}
